const webhookItem = $('Webhook Subida Pasaporte').first();
const rawText = $input.item.json.text || '';
const normText = rawText.replace(/\r\n/g, '\n').trim();
const binaryData = webhookItem.binary;

// Si el texto nativo es insuficiente (< 40 caracteres) o no contiene palabras clave de pasaporte, derivar a OCR LlamaIndex
const isPassportText = /pasaporte|passport|republic|kingdom|nacionalidad|nationality|date of birth/i.test(normText) || /P<[A-Z]{3}/.test(normText);

if (normText.length < 40 || !isPassportText) {
  return [{ json: { __needs_ocr: true, text: normText }, binary: binaryData }];
}

return [{ json: { __needs_ocr: false, markdown: normText }, binary: binaryData }];

const item = $input.item.json;
let rawOutput = item.output || item;
let data = rawOutput.data || {};

// Obtener markdown u ocr crudo de nodos anteriores como red de seguridad
let rawDocText = '';
try {
  rawDocText = $('LlamaParse Get Markdown').first().json.markdown || '';
} catch (e) {}
if (!rawDocText) {
  try {
    rawDocText = $('Evaluar Texto Nativo').first().json.markdown || $('Evaluar Texto Nativo').first().json.text || '';
  } catch (e) {}
}

function cleanVal(v) {
  if (v === null || v === undefined) return '';
  let s = String(v).replace(/[*_#|]/g, '').trim();
  if (s.toLowerCase() === 'null' || s.toLowerCase() === 'undefined' || s === 'N/A' || s === '?' || s.toLowerCase() === 'desconocido') return '';
  return s;
}

let nombre = cleanVal(data.nombre);
let apellidos = cleanVal(data.apellidos);
let pasaporte = cleanVal(data.numero_pasaporte);
let nacionalidad = cleanVal(data.nacionalidad);
let fnac = cleanVal(data.fecha_nacimiento);
let fcad = cleanVal(data.fecha_caducidad);

// Respaldo por expresiones regulares sobre el texto OCR si la IA omitio algun campo
if (rawDocText) {
  const normDoc = rawDocText.replace(/\r\n/g, '\n');

  // Apellidos
  if (!apellidos) {
    const m = normDoc.match(/(?:AP(?:P)?ELLIDOS|SURNAME)[^:\n|]*[:|\n\s]+([A-ZÁÉÍÓÚÑ ]+)/i);
    if (m && !m[1].includes('GIVEN')) apellidos = cleanVal(m[1].split('\n')[0]);
  }

  // Nombre
  if (!nombre) {
    const m = normDoc.match(/(?:NOMBRE|GIVEN NAMES)[^:\n|]*[:|\n\s]+([A-ZÁÉÍÓÚÑ ]+)/i);
    if (m && !m[1].includes('NATIONALITY')) nombre = cleanVal(m[1].split('\n')[0]);
  }

  // Pasaporte
  if (!pasaporte) {
    const m = normDoc.match(/(?:PASSPORT NO|NUMERO DE PASAPORTE|PASSPORT NUMBER)[^:\n|.]*[:|\n\s.]+([A-Z0-9]{6,12})/i);
    if (m) pasaporte = cleanVal(m[1]);
  }

  // Nacionalidad
  if (!nacionalidad) {
    const m = normDoc.match(/(?:NACIONALIDAD|NATIONALITY)[^:\n|]*[:|\n\s]+([A-ZÁÉÍÓÚÑ ()]+)/i);
    if (m) {
      let raw = m[1].split('\n')[0];
      if (/ESP/i.test(raw)) nacionalidad = 'ESP';
      else if (/GBR|BRITISH/i.test(raw)) nacionalidad = 'GBR';
      else nacionalidad = cleanVal(raw);
    }
  }

  // Fechas (DD/MM/YYYY a YYYY-MM-DD)
  if (!fnac) {
    const m = normDoc.match(/(?:FECHA DE NACIMIENTO|DATE OF BIRTH)[^:\n|]*[:|\n\s]+([0-3]?\d[\/.-][0-1]?\d[\/.-]\d{4})/i);
    if (m) {
      const p = m[1].split(/[\/.-]/);
      fnac = `${p[2]}-${p[1].padStart(2, '0')}-${p[0].padStart(2, '0')}`;
    }
  }

  if (!fcad && !normDoc.includes('MANCHA DE TINTA') && !normDoc.includes('████')) {
    const m = normDoc.match(/(?:FECHA DE CADUCIDAD|DATE OF EXPIRY)[^:\n|]*[:|\n\s]+([0-3]?\d[\/.-][0-1]?\d[\/.-]\d{4})/i);
    if (m) {
      const p = m[1].split(/[\/.-]/);
      fcad = `${p[2]}-${p[1].padStart(2, '0')}-${p[0].padStart(2, '0')}`;
    }
  }

  // ZONA MRZ (Machine Readable Zone: P<ESP...)
  const mrz1 = normDoc.match(/P<([A-Z]{3})([A-Z<]+)<<([A-Z<]+)/);
  if (mrz1) {
    if (!nacionalidad) nacionalidad = mrz1[1];
    if (!apellidos) apellidos = mrz1[2].replace(/</g, ' ').trim();
    if (!nombre) nombre = mrz1[3].replace(/</g, ' ').trim();
  }

  const mrz2 = normDoc.match(/([A-Z0-9]{9})\d([A-Z]{3})(\d{6})\d([MF<])(\d{6})/);
  if (mrz2) {
    if (!pasaporte) pasaporte = mrz2[1];
    if (!nacionalidad) nacionalidad = mrz2[2];
    if (!fnac && mrz2[3]) {
      const yy = parseInt(mrz2[3].substring(0, 2), 10);
      const mm = mrz2[3].substring(2, 4);
      const dd = mrz2[3].substring(4, 6);
      const yyyy = yy > 40 ? `19${yy}` : `20${yy}`;
      fnac = `${yyyy}-${mm}-${dd}`;
    }
    if (!fcad && mrz2[5]) {
      const yy = parseInt(mrz2[5].substring(0, 2), 10);
      const mm = mrz2[5].substring(2, 4);
      const dd = mrz2[5].substring(4, 6);
      fcad = `20${yy}-${mm}-${dd}`;
    }
  }
}

// Normalizacion final de fechas
for (const f of [fnac, fcad]) {
  const ddmmyyyy = String(f || '').match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);
  if (ddmmyyyy) {
    f === fnac ? fnac = `${ddmmyyyy[3]}-${ddmmyyyy[2].padStart(2, '0')}-${ddmmyyyy[1].padStart(2, '0')}` : fcad = `${ddmmyyyy[3]}-${ddmmyyyy[2].padStart(2, '0')}-${ddmmyyyy[1].padStart(2, '0')}`;
  }
}

const cleanData = {
  nombre,
  apellidos,
  numero_pasaporte: pasaporte,
  nacionalidad,
  fecha_nacimiento: fnac,
  fecha_caducidad: fcad
};

let pendientes = [];
for (const k of ['nombre', 'apellidos', 'numero_pasaporte', 'nacionalidad', 'fecha_nacimiento', 'fecha_caducidad']) {
  if (!cleanData[k]) pendientes.push(k);
}

const isValid = pendientes.length === 0;

return [{
  json: {
    output: {
      status: isValid ? 'LEGIBLE' : (pendientes.length <= 3 ? 'DUDOSO' : 'ILEGIBLE'),
      valid: isValid,
      message: isValid ? 'Lectura completada y verificada con exito.' : `Lectura parcial: campos pendientes: ${pendientes.join(', ')}`,
      data: cleanData,
      campos_pendientes: pendientes,
      procesado_at: new Date().toISOString()
    }
  }
}];

const webhookItem = $('Webhook Subida Pasaporte').first();
const errorDetail = $input.item.json.error || $input.item.json || {};

return [{
  json: {
    output: {
      status: 'ERROR_IA',
      valid: false,
      message: 'Fallo en la comunicación con el servicio de IA o extracción documental. No se pudieron obtener los datos de forma automatizada.',
      error_tecnico: errorDetail.message || 'Error no especificado en el nodo de IA.',
      data: {
        nombre: '',
        apellidos: '',
        numero_pasaporte: '',
        nacionalidad: '',
        fecha_nacimiento: '',
        fecha_caducidad: ''
      },
      campos_pendientes: [
        'nombre',
        'apellidos',
        'numero_pasaporte',
        'nacionalidad',
        'fecha_nacimiento',
        'fecha_caducidad'
      ],
      procesado_at: new Date().toISOString()
    }
  }
}];

